/* SI units; internal diameter in mm. Pure water only. */
function waterProperties(t){const rho=1000*(1-(t+288.9414)/(508929.2*(t+68.12963))*(t-3.9863)**2);const mu=2.414e-5*10**(247.8/(t+133.15));return{rho,mu};}
function pressurePipe(q,diameter,t,roughness,length){const D=diameter/1000,A=Math.PI*D*D/4,V=q/A,{rho,mu}=waterProperties(t),Re=rho*V*D/mu;let f=64/Re;if(Re>=4000){f=.02;for(let i=0;i<40;i++)f=1/(-2*Math.log10(roughness/1000/(3.7*D)+2.51/(Re*Math.sqrt(f))))**2;}else if(Re>=2300){let turbulent=.03;for(let i=0;i<40;i++)turbulent=1/(-2*Math.log10(roughness/1000/(3.7*D)+2.51/(Re*Math.sqrt(turbulent))))**2;const blend=(Re-2300)/1700;f=(1-blend)*64/Re+blend*turbulent;}const R=f*rho*V*V/(2*D);return{diameter,A,V,Re,f,R,loss:R*length,head:R*length/(rho*9.80665),rho};}
function gravityGeometry(diameter,fill,slope,n){const D=diameter/1000,theta=2*Math.acos(1-2*fill),A=D*D/8*(theta-Math.sin(theta)),P=D*theta/2,Rh=A/P,V=Rh**(2/3)*Math.sqrt(slope)/n;return{A,V,q:A*V,fill,Rh};}
function gravityPipe(q,diameter,slope,n,maxFill){const capacity=gravityGeometry(diameter,maxFill,slope,n);if(q>capacity.q)return{diameter,capacity:capacity.q,overCapacity:true};let low=.000001,high=maxFill;for(let i=0;i<60;i++){const mid=(low+high)/2;if(gravityGeometry(diameter,mid,slope,n).q<q)low=mid;else high=mid;}return{diameter,...gravityGeometry(diameter,(low+high)/2,slope,n),capacity:capacity.q,overCapacity:false};}
if(typeof module!=='undefined')module.exports={waterProperties,pressurePipe,gravityGeometry,gravityPipe};
